const { collect } = require('./collect');

describe('collect()', () => {
  test('returns exactly target unique items across multiple rounds', async () => {
    let call = 0;
    const findCandidates = jest.fn(() => {
      call++;
      if (call === 1) return ['a', 'b'];
      return ['b', 'c'];
    });

    const result = await collect(3, findCandidates);

    expect(result).toEqual(['a', 'b', 'c']);
    expect(findCandidates).toHaveBeenCalledTimes(2);
