  test('stops after the first round when one round is sufficient', async () => {
    const findCandidates = jest.fn().mockReturnValue(['x', 'y', 'z', 'w']);

    const result = await collect(2, findCandidates);

    expect(result).toHaveLength(2);
    expect(result).toEqual(['x', 'y']);
    expect(findCandidates).toHaveBeenCalledTimes(1);
  });

  test('deduplicates items within a single round', async () => {
    const findCandidates = jest.fn().mockReturnValue(['a', 'a', 'b', 'b', 'c']);

    const result = await collect(3, findCandidates);

    expect(result).toEqual(['a', 'b', 'c']);
    expect(findCandidates).toHaveBeenCalledTimes(1);
  });

  test('logs new item count and running total each round', async () => {
    const logs = [];
    const findCandidates = jest.fn()
      .mockReturnValueOnce(['a', 'b', 'a'])  // 2 new → total 2
      .mockReturnValueOnce(['b', 'c']);       // 1 new → total 3

    await collect(3, findCandidates, { log: (msg) => logs.push(msg) });

    expect(logs).toEqual([
      'Round 1: +2 new (2 total)',
      'Round 2: +1 new (3 total)',
    ]);
  });

  test('logs zero new items when a round contributes nothing novel', async () => {
    const logs = [];
    const findCandidates = jest.fn()
      .mockReturnValueOnce(['a', 'b'])   // 2 new → total 2
      .mockReturnValueOnce(['a', 'b'])   // 0 new → total 2
      .mockReturnValueOnce(['c']);        // 1 new → total 3

    await collect(3, findCandidates, { log: (msg) => logs.push(msg) });

    expect(logs).toEqual([
      'Round 1: +2 new (2 total)',
      'Round 2: +0 new (2 total)',
      'Round 3: +1 new (3 total)',
    ]);
  });

  test('uses console.log by default (smoke test)', async () => {
    const spy = jest.spyOn(console, 'log').mockImplementation(() => {});
    const findCandidates = jest.fn().mockReturnValue(['a', 'b', 'c']);

    await collect(3, findCandidates);

    expect(spy).toHaveBeenCalledWith('Round 1: +3 new (3 total)');
    spy.mockRestore();
